const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-70.647985, -34.752733);
  // Define a buffer around the point to represent the basin for analysis
  const geometry = point.buffer(20000); // 20 km buffer

  const targetDate2023 = '2023-12-18';
  const targetDateEnd2023 = '2023-12-19'; // End date is exclusive

  const historicalStartYear = 2017;
  const historicalEndYear = 2022;

  // Define scale for area calculation. MODIS is 500m. Using 1000m for reduceRegion.
  const scale = 1000;

  // 2. Data Acquisition
  const collection = ee.ImageCollection('MODIS/051/MOD10A1')
    .select('NDSI_Snow_Cover');

  // Function to mask non-snow and cloud pixels
  function maskSnow(image) {
    // NDSI_Snow_Cover values:
    // 1-100: Snow cover
    // 200: Lake
    // 201: Land (no snow)
    // 211: Night
    // 250: Cloud
    // 254: Detector saturation
    // 255: No data
    return image.updateMask(image.gt(0).and(image.lte(100)));
  }

  // Calculate snow area for a given image
  function calculateSnowArea(image, geom) {
    const snow = maskSnow(image);
    const snowArea = snow.gt(0).multiply(ee.Image.pixelArea()); // Calculate area of snow pixels in m^2
    const totalSnowArea = snowArea.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover'); // The band name is NDSI_Snow_Cover after updateMask, and value is pixelArea

    return ee.Number(totalSnowArea).divide(1e6); // Convert m^2 to km^2
  }

  // --- Process 2023 data ---
  let collection2023 = collection.filterDate(targetDate2023, targetDateEnd2023)
    .filterBounds(geometry);

  if (collection2023.size().getInfo() === 0) {
    console.log("No images found for Dec 18, 2023.");
    console.log("C1");
    return;
  }

  // Get the single image for 2023 (or mosaic if multiple exist for a day, although unlikely for MOD10A1)
  const image2023 = collection2023.mosaic();

  const snowArea2023 = await calculateSnowArea(image2023, geometry).getInfo();

  if (snowArea2023 === null || isNaN(snowArea2023)) {
    console.log("Calculation failed for 2023 snow cover.");
    console.log("C3");
    return;
  }

  // Check if no valid pixels remain after masking for 2023
  const count2023 = await image2023.select('NDSI_Snow_Cover')
    .updateMask(image2023.select('NDSI_Snow_Cover').gt(0).and(image2023.select('NDSI_Snow_Cover').lte(100)))
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover').getInfo();

  if (count2023 === 0) {
    console.log(`2023 images: ${collection2023.size().getInfo()} (Val: 0.00km^2), Pixels: 0`);
    console.log("No valid snow pixels after masking for 2023.");
    console.log("C2");
    return;
  }
  console.log(`2023 Snow Cover Extent: ${snowArea2023.toFixed(2)} km^2, Pixels: ${count2023}`);


  // --- Process historical data ---
  let historicalSnowAreas = [];
  let historicalImageCount = 0;
  let historicalValidPixelCount = 0;

  for (let year = historicalStartYear; year <= historicalEndYear; year++) {
    const start = `${year}-12-18`;
    const end = `${year}-12-19`;

    let historicalCollection = collection.filterDate(start, end)
      .filterBounds(geometry);

    if (historicalCollection.size().getInfo() > 0) {
      historicalImageCount += historicalCollection.size().getInfo();
      const historicalImage = historicalCollection.mosaic();
      const area = await calculateSnowArea(historicalImage, geometry).getInfo();

      const count = await historicalImage.select('NDSI_Snow_Cover')
        .updateMask(historicalImage.select('NDSI_Snow_Cover').gt(0).and(historicalImage.select('NDSI_Snow_Cover').lte(100)))
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geometry,
          scale: scale,
          maxPixels: 1e9
        }).get('NDSI_Snow_Cover').getInfo();

      historicalValidPixelCount += count;

      if (area !== null && !isNaN(area)) {
        historicalSnowAreas.push(area);
        console.log(`  ${year} Snow Cover: ${area.toFixed(2)} km^2, Pixels: ${count}`);
      } else {
        console.log(`  ${year} Calculation failed for snow cover. Pixels: ${count}`);
      }
    } else {
      console.log(`  No images found for Dec 18, ${year}.`);
    }
  }

  if (historicalSnowAreas.length === 0) {
    if (historicalImageCount === 0) {
      console.log("C1");
      return;
    } else {
      console.log("No valid historical snow areas could be calculated (after masking/processing).");
      console.log("C2");
      return;
    }
  }

  const averageHistoricalSnowArea = historicalSnowAreas.reduce((a, b) => a + b, 0) / historicalSnowAreas.length;

  if (averageHistoricalSnowArea === null || isNaN(averageHistoricalSnowArea)) {
    console.log("Calculation failed for average historical snow cover.");
    console.log("C3");
    return;
  }

  if (historicalValidPixelCount === 0) {
    console.log(`Historical average: ${averageHistoricalSnowArea.toFixed(2)} km^2, Total Images: ${historicalImageCount}, Total Valid Pixels: 0`);
    console.log("No valid historical pixels after masking.");
    console.log("C2");
    return;
  }

  console.log(`Historical average (2017-2022) Snow Cover Extent: ${averageHistoricalSnowArea.toFixed(2)} km^2`);

  // 5. Validation & Final Answer
  if (snowArea2023 > averageHistoricalSnowArea) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
